from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="API utilisateurs")
utilisateurs: dict[int, dict] = {}

class UtilisateurIn(BaseModel):
    nom: str
    email: str

@app.post("/users/", status_code=201)
def creer(u: UtilisateurIn):
    uid = len(utilisateurs) + 1
    utilisateurs[uid] = u.model_dump()
    return {"id": uid, **utilisateurs[uid]}

@app.get("/users/{uid}")
def lire(uid: int):
    if uid not in utilisateurs:
        raise HTTPException(status_code=404, detail="Utilisateur introuvable")
    return {"id": uid, **utilisateurs[uid]}

@app.delete("/users/{uid}", status_code=204)
def supprimer(uid: int):
    utilisateurs.pop(uid, None)

