from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()
notes: dict[int, str] = {}

class Note(BaseModel):
    texte: str

@app.post("/notes", status_code=201)
def creer(n: Note):
    nid = max(notes, default=0) + 1
    notes[nid] = n.texte
    return {"id": nid, "texte": n.texte}

@app.get("/notes/{nid}")
def lire(nid: int):
    if nid not in notes:
        raise HTTPException(404, "Note introuvable")
    return {"id": nid, "texte": notes[nid]}

@app.delete("/notes/{nid}", status_code=204)
def supprimer(nid: int):
    notes.pop(nid, None)

def test_cycle_de_vie():
    c = TestClient(app)
    nid = c.post("/notes", json={"texte": "réviser"}).json()["id"]
    assert c.get(f"/notes/{nid}").json()["texte"] == "réviser"
    assert c.delete(f"/notes/{nid}").status_code == 204
    assert c.get(f"/notes/{nid}").status_code == 404
